package si.spindl.reports;

import jakarta.persistence.EntityManager;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.TenantAuditEventEntity;
import si.spindl.identity.TenantAuditEventRepository;
import si.spindl.tenant.DevelopmentTenant;
import java.util.*;

@Service
public class ReportBuilderService {
    private record Source(String table,Map<String,String> columns,String orderColumn){private Source(String table,Map<String,String> columns){this(table,columns,"created_at");}}
    private final DevelopmentTenant tenant;private final SavedReportRepository reports;private final EntityManager entityManager;private final TenantAuditEventRepository audit;
    public ReportBuilderService(DevelopmentTenant tenant,SavedReportRepository reports,EntityManager entityManager,TenantAuditEventRepository audit){this.tenant=tenant;this.reports=reports;this.entityManager=entityManager;this.audit=audit;}

    @Transactional(readOnly=true) public List<SourceView> sources(){return sourceCatalog().entrySet().stream().map(entry->new SourceView(entry.getKey(),label(entry.getKey()),entry.getValue().columns().keySet().stream().map(key->new ColumnView(key,label(key),typeOf(key))).toList())).toList();}
    @Transactional(readOnly=true) public List<ReportView> list(){return reports.findAllByTenantIdOrderByUpdatedAtDesc(tenant.currentTenantId()).stream().map(ReportView::from).toList();}
    @Transactional public ReportView create(UUID actorId,CreateRequest request){UUID tenantId=tenant.currentTenantId();String name=request.name().trim();if(name.isBlank())throw badRequest("Report name is required");if(reports.existsByTenantIdAndNameIgnoreCase(tenantId,name))throw conflict("A saved report already uses this name");List<String> columns=validateColumns(request.dataSource(),request.columns());List<Map<String,String>> filters=validateFilters(request.dataSource(),request.filters()).stream().map(BoundFilter::toMap).toList();String groupBy=validateGroupBy(request.dataSource(),request.groupBy());List<ReportMetric> requestedMetrics=request.metrics()==null?List.of():request.metrics().stream().map(metric->metric==null?null:new ReportMetric(metric.function(),metric.field())).toList();List<Map<String,String>> metrics=validateMetrics(request.dataSource(),requestedMetrics).stream().map(ReportMetric::toMap).toList();if(groupBy==null&&!metrics.isEmpty())throw badRequest("Choose a group field when adding report metrics");var report=reports.save(new SavedReportEntity(tenantId,name,request.dataSource(),columns,filters,groupBy,metrics,actorId));audit.save(new TenantAuditEventEntity(tenantId,actorId,"SAVED_REPORT_CREATED","saved_report",report.getId(),Map.of("name",name,"dataSource",request.dataSource(),"columnCount",columns.size(),"filterCount",filters.size(),"grouped",groupBy!=null,"metricCount",metrics.size())));return ReportView.from(report);}
    @Transactional public void delete(UUID actorId,UUID id){UUID tenantId=tenant.currentTenantId();var report=reports.findByTenantIdAndId(tenantId,id).orElseThrow(()->notFound("Saved report not found"));reports.delete(report);audit.save(new TenantAuditEventEntity(tenantId,actorId,"SAVED_REPORT_DELETED","saved_report",id,Map.of("name",report.getName())));}
    @Transactional(readOnly=true) public RunResult run(UUID id,String search,int page,int size){return runForTenant(tenant.currentTenantId(),id,search,page,size);}
    @Transactional(readOnly=true) public RunResult runForTenant(UUID tenantId,UUID id,String search,int page,int size){if(page<0||size<1||size>100)throw badRequest("Page must be non-negative and page size must be between 1 and 100");if(search!=null&&search.length()>120)throw badRequest("Search text is limited to 120 characters");SavedReportEntity report=reports.findByTenantIdAndId(tenantId,id).orElseThrow(()->notFound("Saved report not found"));Source source=sourceCatalog().get(report.getDataSource());List<String> columns=validateColumns(report.getDataSource(),report.getSelectedColumns());List<BoundFilter> filters=validateFilters(report.getDataSource(),report.getFilters().stream().map(BoundFilter::fromMap).toList());String groupBy=validateGroupBy(report.getDataSource(),report.getGroupBy());List<ReportMetric> metrics=validateMetrics(report.getDataSource(),report.getMetrics().stream().map(ReportMetric::fromMap).toList());boolean grouped=groupBy!=null;List<String> outputColumns=new ArrayList<>();String select;
        if(grouped){String groupExpression=source.columns().get(groupBy);outputColumns.add("groupValue");List<String> selections=new ArrayList<>(List.of(groupExpression+" AS \"groupValue\""));for(ReportMetric metric:metrics){String alias=metric.alias();outputColumns.add(alias);selections.add(metric.expression(source)+" AS \""+alias+"\"");}select=String.join(", ",selections);}else{select=columns.stream().map(column->source.columns().get(column)+" AS \""+column+"\"").collect(java.util.stream.Collectors.joining(", "));outputColumns.addAll(columns);}
        StringBuilder where=new StringBuilder(" WHERE tenant_id = :tenantId");String queryText=search==null?"":search.trim();if(!queryText.isEmpty())where.append(" AND (").append(columns.stream().map(column->"CAST("+source.columns().get(column)+" AS text) ILIKE :search").collect(java.util.stream.Collectors.joining(" OR "))).append(")");for(int i=0;i<filters.size();i++)where.append(" AND ").append(filters.get(i).sql(source,i));String sqlWhere=where.toString();String groupClause=grouped?" GROUP BY "+source.columns().get(groupBy):"";String order=grouped?" ORDER BY \"groupValue\" ASC NULLS FIRST":" ORDER BY "+source.orderColumn()+" DESC NULLS LAST, id ASC";var dataQuery=entityManager.createNativeQuery("SELECT "+select+" FROM "+source.table()+sqlWhere+groupClause+order);var countQuery=entityManager.createNativeQuery(grouped?"SELECT count(*) FROM (SELECT 1 FROM "+source.table()+sqlWhere+groupClause+") grouped_rows":"SELECT count(*) FROM "+source.table()+sqlWhere);dataQuery.setParameter("tenantId",tenantId);countQuery.setParameter("tenantId",tenantId);if(!queryText.isEmpty()){dataQuery.setParameter("search","%"+queryText+"%");countQuery.setParameter("search","%"+queryText+"%");}for(int i=0;i<filters.size();i++){dataQuery.setParameter("filter"+i,filters.get(i).typedValue());countQuery.setParameter("filter"+i,filters.get(i).typedValue());}dataQuery.setFirstResult(Math.multiplyExact(page,size));dataQuery.setMaxResults(size);List<?> raw=dataQuery.getResultList();List<Map<String,Object>> rows=raw.stream().map(result->{Object[] values=result instanceof Object[] array?array:new Object[]{result};var row=new LinkedHashMap<String,Object>();for(int index=0;index<outputColumns.size();index++)row.put(outputColumns.get(index),values[index]);return (Map<String,Object>)row;}).toList();long total=((Number)countQuery.getSingleResult()).longValue();return new RunResult(report.getName(),report.getDataSource(),outputColumns,total,page,size,rows);}

    private List<String> validateColumns(String dataSource,List<String> requested){Source source=sourceCatalog().get(dataSource);if(source==null)throw badRequest("Choose a supported report data source");if(requested==null||requested.isEmpty()||requested.size()>12)throw badRequest("Select between 1 and 12 report columns");if(requested.stream().distinct().count()!=requested.size()||requested.stream().anyMatch(column->!source.columns().containsKey(column)))throw badRequest("One or more selected columns are not available for this data source");return List.copyOf(requested);}
    private List<BoundFilter> validateFilters(String sourceKey,List<ReportFilter> filters){if(filters==null||filters.isEmpty())return List.of();if(filters.size()>8)throw badRequest("A report can have at most eight filters");Source source=sourceCatalog().get(sourceKey);if(source==null)throw badRequest("Choose a supported report data source");List<BoundFilter> result=new ArrayList<>();Set<String> fields=new HashSet<>();for(ReportFilter filter:filters){if(filter==null||!source.columns().containsKey(filter.field()))throw badRequest("Choose a filter field in this report data source");String type=typeOf(filter.field());String operator=filter.operator()==null?"":filter.operator().trim().toLowerCase(Locale.ROOT);Set<String> allowed=switch(type){case "number","date"->Set.of("equals","greater_than","at_least","less_than","at_most");case "boolean"->Set.of("equals");default->Set.of("equals","contains");};if(!allowed.contains(operator))throw badRequest("Choose a supported operator for "+label(filter.field()));String value=filter.value()==null?"":filter.value().trim();if(value.isEmpty()||value.length()>120)throw badRequest("Filter values must contain 1 to 120 characters");String unique=filter.field()+":"+operator;if(!fields.add(unique))throw badRequest("Each report field and operator can only be filtered once");Object typed;try{typed=switch(type){case "number"->new java.math.BigDecimal(value);case "boolean"->{if(!value.equalsIgnoreCase("true")&&!value.equalsIgnoreCase("false"))throw new IllegalArgumentException();yield Boolean.valueOf(value);}case "date"->java.time.LocalDate.parse(value);default->value;};}catch(RuntimeException exception){throw badRequest("Enter a valid "+type+" value for "+label(filter.field()));}result.add(new BoundFilter(filter.field(),operator,value,typed,type));}return List.copyOf(result);}
    private String typeOf(String key){if("active".equals(key))return "boolean";if(Set.of("onHand","reservedQuantity","unitPrice","total","amountPaid","creditTotal","quantityChange").contains(key))return "number";if("dueDate".equals(key))return "date";return "text";}
    private String validateGroupBy(String sourceKey,String groupBy){if(groupBy==null||groupBy.isBlank())return null;Source source=sourceCatalog().get(sourceKey);if(source==null||!source.columns().containsKey(groupBy))throw badRequest("Choose a group field available in this report data source");return groupBy;}
    private List<ReportMetric> validateMetrics(String sourceKey,List<ReportMetric> metrics){if(metrics==null||metrics.isEmpty())return List.of();if(metrics.size()>4)throw badRequest("A report can have at most four metrics");Source source=sourceCatalog().get(sourceKey);if(source==null)throw badRequest("Choose a supported report data source");List<ReportMetric> result=new ArrayList<>();Set<String> aliases=new HashSet<>();for(ReportMetric metric:metrics){if(metric==null)throw badRequest("Choose a valid report metric");String fn=metric.function()==null?"":metric.function().trim().toLowerCase(Locale.ROOT);String field=metric.field()==null?"":metric.field().trim();if(!Set.of("count","sum","average","minimum","maximum").contains(fn))throw badRequest("Choose a supported report aggregation");if(fn.equals("count")&&field.equals("*")){field="*";}else if(!source.columns().containsKey(field))throw badRequest("Choose a metric field available in this report data source");if(!fn.equals("count")&&!"number".equals(typeOf(field)))throw badRequest("Only numeric fields support sum, average, minimum, or maximum");ReportMetric normalized=new ReportMetric(fn,field);if(!aliases.add(normalized.alias()))throw badRequest("Each report metric can only be selected once");result.add(normalized);}return List.copyOf(result);}
    private record ReportMetric(String function,String field){String alias(){String f=switch(function){case "average"->"avg";case "minimum"->"min";case "maximum"->"max";default->function;};return field.equals("*")?f+"Rows":f+"_"+field;}String expression(Source source){return switch(function){case "count"->field.equals("*")?"COUNT(*)":"COUNT("+source.columns().get(field)+")";case "sum"->"SUM("+source.columns().get(field)+")";case "average"->"AVG("+source.columns().get(field)+")";case "minimum"->"MIN("+source.columns().get(field)+")";case "maximum"->"MAX("+source.columns().get(field)+")";default->throw new IllegalStateException("Unvalidated report aggregation");};}Map<String,String> toMap(){return Map.of("function",function,"field",field);}static ReportMetric fromMap(Map<String,String> map){return new ReportMetric(map.get("function"),map.get("field"));}}
    private Map<String,Source> sourceCatalog(){var catalog=new LinkedHashMap<String,Source>();catalog.put("customers",new Source("customers",columns("id","id","code","code","name","name","email","email","status","status","active","active","createdAt","created_at")));catalog.put("suppliers",new Source("suppliers",columns("id","id","code","code","name","name","email","email","status","status","active","active","createdAt","created_at")));catalog.put("items",new Source("items",columns("id","id","sku","sku","name","name","category","category","itemType","item_type","onHand","on_hand","reservedQuantity","reserved_quantity","unit","unit","unitPrice","unit_price","active","active","createdAt","created_at")));catalog.put("inventoryMovements",new Source("inventory_movements",columns("id","id","itemId","item_id","warehouseId","warehouse_id","quantityChange","quantity_delta","reason","reason","sourceReference","source_reference","createdAt","created_at")));catalog.put("salesOrders",new Source("sales_orders",columns("id","id","orderNumber","order_number","customerId","customer_id","status","status","createdAt","created_at")));catalog.put("purchaseOrders",new Source("purchase_orders",columns("id","id","orderNumber","order_number","supplierId","supplier_id","status","status","notes","notes","createdAt","created_at")));catalog.put("invoices",new Source("invoices",columns("id","id","invoiceNumber","invoice_number","salesOrderId","sales_order_id","customerId","customer_id","status","status","dueDate","due_date","total","total","amountPaid","amount_paid","creditTotal","credit_total","issuedAt","issued_at"),"issued_at"));return catalog;}
    private Map<String,String> columns(String...pairs){var columns=new LinkedHashMap<String,String>();for(int i=0;i<pairs.length;i+=2)columns.put(pairs[i],pairs[i+1]);return Collections.unmodifiableMap(columns);}
    private String label(String value){String spaced=value.replaceAll("([a-z0-9])([A-Z])","$1 $2").replace('_',' ');return Arrays.stream(spaced.split(" ")).filter(part->!part.isBlank()).map(part->part.substring(0,1).toUpperCase(Locale.ROOT)+part.substring(1)).collect(java.util.stream.Collectors.joining(" "));}
    private ResponseStatusException badRequest(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}private ResponseStatusException notFound(String message){return new ResponseStatusException(HttpStatus.NOT_FOUND,message);}

    public record CreateRequest(String name,String dataSource,List<String> columns,List<ReportFilter> filters,String groupBy,List<ReportMetricInput> metrics){}
    public record ReportMetricInput(String function,String field){}
    public record ReportFilter(String field,String operator,String value){}
    private record BoundFilter(String field,String operator,String value,Object typedValue,String type){String sql(Source source,int index){String expression=source.columns().get(field);if(type.equals("text"))expression="CAST("+expression+" AS text)";String parameter=":filter"+index;return switch(operator){case "equals"->expression+" = "+parameter;case "contains"->expression+" ILIKE "+parameter;case "greater_than"->expression+" > "+parameter;case "at_least"->expression+" >= "+parameter;case "less_than"->expression+" < "+parameter;case "at_most"->expression+" <= "+parameter;default->throw new IllegalStateException("Unvalidated report filter");};}Map<String,String> toMap(){return Map.of("field",field,"operator",operator,"value",value);}static ReportFilter fromMap(Map<String,String> map){return new ReportFilter(map.get("field"),map.get("operator"),map.get("value"));}}
    public record ColumnView(String key,String label,String type){}
    public record SourceView(String key,String label,List<ColumnView> columns){}
    public record ReportView(UUID id,String name,String dataSource,List<String> columns,List<Map<String,String>> filters,String groupBy,List<Map<String,String>> metrics,java.time.Instant createdAt,java.time.Instant updatedAt){static ReportView from(SavedReportEntity report){return new ReportView(report.getId(),report.getName(),report.getDataSource(),report.getSelectedColumns(),report.getFilters(),report.getGroupBy(),report.getMetrics(),report.getCreatedAt(),report.getUpdatedAt());}}
    public record RunResult(String name,String dataSource,List<String> columns,long totalElements,int page,int pageSize,List<Map<String,Object>> rows){}
}
